document.querySelectorAll(".faq-q").forEach(t=>t.addEventListener("click",()=>t.parentElement.classList.toggle("open")));const menuBtn=document.querySelector(".menu-btn"),menu=document.getElementById("mobileMenu");if(menuBtn&&menu){const t=e=>{menu.classList.toggle("open",e),menuBtn.setAttribute("aria-expanded",e),menuBtn.setAttribute("aria-label",e?"Fermer le menu":"Ouvrir le menu"),menuBtn.textContent=e?"\u2715":"\u2630"};menuBtn.addEventListener("click",()=>t(!menu.classList.contains("open"))),menu.querySelectorAll("a").forEach(e=>e.addEventListener("click",()=>t(!1)))}
